// Feed registry. category must match the Telegram topic router in workflow 04.
const feeds = [
  { url: 'https://feeds.feedburner.com/TheHackersNews', source: 'thehackernews', category: 'hack' },
  { url: 'https://www.bleepingcomputer.com/feed/', source: 'bleepingcomputer', category: 'hack' },
  { url: 'https://krebsonsecurity.com/feed/', source: 'krebs', category: 'hack' },
  { url: 'https://hnrss.org/newest?q=jailbreak+OR+LLM+security', source: 'hackernews', category: 'ai' },
  { url: 'https://huggingface.co/blog/feed.xml', source: 'huggingface', category: 'ai' },
  { url: 'https://github.com/danielmiessler/fabric/releases.atom', source: 'github:fabric', category: 'ai' },
  { url: 'https://github.com/projectdiscovery/nuclei/releases.atom', source: 'github:nuclei', category: 'hack' },
  { url: 'https://github.com/elder-plinius/L1B3RT4S/commits/main.atom', source: 'github:liberatas', category: 'ai' }
];
return feeds.map(feed => ({ json: feed }));

// Normalise RSS + GitHub Atom entries into the news_items shape.
const out = [];
const maxAgeHours = Number($env.RADAR_MAX_AGE_HOURS || 48);
for (const item of $input.all()) {
  const j = item.json;
  const paired = $('Feed Registry').all();
  const feed = paired[item.pairedItem?.item ?? 0]?.json ?? paired[0].json;
  const url = j.link || j.id || j.guid;
  if (!url) continue;
  const published = j.isoDate || j.pubDate || j.updated || new Date().toISOString();
  const ageHours = (Date.now() - new Date(published).getTime()) / 3600000;
  if (Number.isFinite(ageHours) && ageHours > maxAgeHours) continue;
  const summary = String(j.contentSnippet || j.content || j.summary || '')
    .replace(/<[^>]+>/g, ' ')
    .replace(/\s+/g, ' ')
    .trim()
    .slice(0, 1500);
  out.push({
    json: {
      url: String(url),
      title: String(j.title || '').trim().slice(0, 400),
      summary,
      source: feed.source,
      category: feed.category,
      published_at: new Date(published).toISOString()
    }
  });
}
return out;
